package s2

import (
	"bytes"
	"math/rand"
	"reflect"
	"testing"

	"github.com/golang/geo/s1"
)

func shapeIndexRoundTrip(t *testing.T, index *ShapeIndex) *ShapeIndex {
	t.Helper()
	var buf bytes.Buffer
	if err := index.Encode(&buf); err != nil {
		t.Fatalf("Encode() = %v", err)
	}
	if buf.Len() == 0 {
		t.Fatalf("Encode() produced no bytes")
	}
	got := NewShapeIndex()
	if err := got.Decode(&buf); err != nil {
		t.Fatalf("Decode() = %v", err)
	}
	return got
}

func checkShapeIndexEqual(t *testing.T, got, want *ShapeIndex) {
	t.Helper()
	want.Build()
	if !got.IsFresh() {
		t.Errorf("decoded index is not fresh")
	}
	if got.Len() != want.Len() || got.nextID != want.nextID {
		t.Fatalf("Len, nextID = %d, %d, want %d, %d", got.Len(), got.nextID, want.Len(), want.nextID)
	}
	if got.maxEdgesPerCell != want.maxEdgesPerCell {
		t.Errorf("maxEdgesPerCell = %d, want %d", got.maxEdgesPerCell, want.maxEdgesPerCell)
	}
	for id, ws := range want.shapes {
		gs := got.Shape(id)
		if gs == nil {
			t.Fatalf("shape %d missing", id)
		}
		if reflect.TypeOf(gs) != reflect.TypeOf(ws) {
			t.Errorf("shape %d type = %T, want %T", id, gs, ws)
		}
		if gs.Dimension() != ws.Dimension() || gs.NumEdges() != ws.NumEdges() ||
			gs.NumChains() != ws.NumChains() || gs.IsEmpty() != ws.IsEmpty() || gs.IsFull() != ws.IsFull() {
			t.Fatalf("shape %d properties differ", id)
		}
		if gs.ReferencePoint() != ws.ReferencePoint() {
			t.Errorf("shape %d ReferencePoint = %v, want %v", id, gs.ReferencePoint(), ws.ReferencePoint())
		}
		for e := 0; e < ws.NumEdges(); e++ {
			if gs.Edge(e) != ws.Edge(e) {
				t.Errorf("shape %d edge %d = %v, want %v", id, e, gs.Edge(e), ws.Edge(e))
			}
			if gs.ChainPosition(e) != ws.ChainPosition(e) {
				t.Errorf("shape %d ChainPosition(%d) = %v, want %v", id, e, gs.ChainPosition(e), ws.ChainPosition(e))
			}
		}
		for c := 0; c < ws.NumChains(); c++ {
			if gs.Chain(c) != ws.Chain(c) {
				t.Errorf("shape %d chain %d = %v, want %v", id, c, gs.Chain(c), ws.Chain(c))
			}
		}
	}
	if !reflect.DeepEqual(got.cells, want.cells) {
		t.Fatalf("cells = %v, want %v", got.cells, want.cells)
	}
	for _, id := range want.cells {
		if !reflect.DeepEqual(got.cellMap[id], want.cellMap[id]) {
			t.Errorf("cell %v = %+v, want %+v", id, got.cellMap[id], want.cellMap[id])
		}
	}

	// Iteration must visit the same cells without rebuilding.
	gi, wi := got.Iterator(), want.Iterator()
	for ; !wi.Done(); wi.Next() {
		if gi.Done() || gi.CellID() != wi.CellID() {
			t.Fatalf("iterator mismatch at %v", wi.CellID())
		}
		gi.Next()
	}
	if !gi.Done() {
		t.Errorf("decoded iterator has extra cells")
	}
}

func allShapeTypesIndex() *ShapeIndex {
	index := NewShapeIndex()
	index.Add(makePolygon("0:0, 0:10, 10:10, 10:0; 2:2, 8:2, 8:8, 2:8", true))
	index.Add(makeLoop("20:20, 20:25, 25:25"))
	index.Add(makePolyline("-10:-10, -20:-20, -30:-25"))
	pv := PointVector(parsePoints("40:40, 41:41, 42:-42"))
	index.Add(&pv)
	index.Add(makeLaxPolyline("-40:40, -45:45, -40:50"))
	index.Add(LaxLoopFromPoints(parsePoints("60:60, 60:65, 65:65, 65:60")))
	index.Add(makeLaxPolygon("1:100, 1:110, 10:110; full; 20:100, 20:110, 30:110"))
	index.Add(FullPolygon())
	index.Add(&edgeVectorShape{edges: []Edge{{PointFromCoords(1, 0, 0), PointFromCoords(0, 1, 0)}}})
	return index
}

func TestShapeIndexEncodeAllShapeTypes(t *testing.T) {
	index := allShapeTypesIndex()
	index.Build()
	got := shapeIndexRoundTrip(t, index)
	checkShapeIndexEqual(t, got, index)

	// Queries work without Build.
	wq := NewContainsPointQuery(index, VertexModelSemiOpen)
	gq := NewContainsPointQuery(got, VertexModelSemiOpen)
	for i := 0; i < 1000; i++ {
		p := randomPoint()
		if gq.Contains(p) != wq.Contains(p) {
			t.Fatalf("Contains(%v) differs", p)
		}
	}
	for _, p := range parsePoints("5:5, 1:1, 22:21, 5:105, 25:105") {
		if gq.Contains(p) != wq.Contains(p) {
			t.Errorf("Contains(%v) = %v, want %v", p, gq.Contains(p), wq.Contains(p))
		}
	}
}

func TestShapeIndexEncodeEmpty(t *testing.T) {
	index := NewShapeIndex()
	got := shapeIndexRoundTrip(t, index)
	checkShapeIndexEqual(t, got, index)
	if got.Len() != 0 || len(got.cells) != 0 {
		t.Errorf("decoded empty index is not empty")
	}
}

func TestShapeIndexEncodeZeroEdgeShapes(t *testing.T) {
	index := NewShapeIndex()
	index.Add(&Polygon{})
	index.Add(&PointVector{})
	index.Add(&Polyline{})
	index.Add(LaxPolylineFromPoints(parsePoints("1:1")))
	index.Add(LaxLoopFromPoints(nil))
	index.Add(LaxPolygonFromPoints(nil))
	index.Add(LaxPolygonFromPoints([][]Point{{}}))
	index.Add(LaxPolygonFromPoints([][]Point{{}, parsePoints("0:0, 0:1, 1:1"), {}}))
	index.Add(EmptyLoop())
	index.Add(FullLoop())
	got := shapeIndexRoundTrip(t, index)
	checkShapeIndexEqual(t, got, index)
}

func TestShapeIndexEncodeWithoutBuild(t *testing.T) {
	index := allShapeTypesIndex()
	var buf bytes.Buffer
	if err := index.Encode(&buf); err != nil {
		t.Fatalf("Encode() = %v", err)
	}
	got := NewShapeIndex()
	if err := got.Decode(&buf); err != nil {
		t.Fatalf("Decode() = %v", err)
	}
	if len(got.cells) == 0 {
		t.Fatalf("decoded index has no cells")
	}
	checkShapeIndexEqual(t, got, index)
}

func TestShapeIndexEncodePreservesShapeIDs(t *testing.T) {
	index := NewShapeIndex()
	var loops []*Loop
	for i := 0; i < 6; i++ {
		l := RegularLoop(PointFromLatLng(LatLngFromDegrees(float64(10*i), 0)), s1.Degree, 8)
		loops = append(loops, l)
		index.Add(l)
	}
	index.Build()
	index.Remove(loops[1])
	index.Remove(loops[4])
	index.Remove(loops[5])

	got := shapeIndexRoundTrip(t, index)
	checkShapeIndexEqual(t, got, index)
	for _, id := range []int32{1, 4, 5} {
		if got.Shape(id) != nil {
			t.Errorf("removed shape %d present after decode", id)
		}
	}

	// The decoded index keeps working with incremental updates.
	newLoop := RegularLoop(PointFromLatLng(LatLngFromDegrees(-30, 30)), s1.Degree, 8)
	if id := got.Add(newLoop); id != 6 {
		t.Errorf("Add() after decode = %d, want 6", id)
	}
	index.Add(RegularLoop(PointFromLatLng(LatLngFromDegrees(-30, 30)), s1.Degree, 8))
	got.Remove(got.Shape(0))
	index.Remove(loops[0])
	checkShapeIndexEqual(t, got, index)
}

func TestShapeIndexEncodeLarge(t *testing.T) {
	index := NewShapeIndex()
	index.Add(concentricLoopsPolygon(PointFromCoords(1, 0, 0), 10, 50))
	pts := make(PointVector, 500)
	for i := range pts {
		pts[i] = randomPoint()
	}
	index.Add(&pts)
	got := shapeIndexRoundTrip(t, index)
	checkShapeIndexEqual(t, got, index)
}

func TestShapeIndexDecodeMalformed(t *testing.T) {
	var buf bytes.Buffer
	if err := allShapeTypesIndex().Encode(&buf); err != nil {
		t.Fatalf("Encode() = %v", err)
	}
	data := buf.Bytes()

	// Every truncation must fail.
	for i := 0; i < len(data); i++ {
		if err := NewShapeIndex().Decode(bytes.NewReader(data[:i])); err == nil {
			t.Fatalf("Decode(data[:%d]) succeeded, want error", i)
		}
	}

	// Corrupted bytes must never panic.
	r := rand.New(rand.NewSource(1))
	for i := 0; i < 2000; i++ {
		c := append([]byte(nil), data...)
		for j := 0; j < 1+r.Intn(4); j++ {
			c[r.Intn(len(c))] = byte(r.Intn(256))
		}
		index := NewShapeIndex()
		if err := index.Decode(bytes.NewReader(c)); err == nil {
			// If it decoded, it must be usable.
			NewContainsPointQuery(index, VertexModelSemiOpen).Contains(randomPoint())
		}
	}

	// Oversized length prefixes must be rejected without allocating.
	huge := []byte{0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x7f}
	for _, tc := range [][]byte{
		{},
		{2},
		append([]byte{shapeIndexEncodingVersion}, huge...),
		append([]byte{shapeIndexEncodingVersion, 10, 0x80, 0x80, 0x80, 0x80, 0x07}, huge...),
		// One polyline claiming an enormous vertex count.
		append([]byte{shapeIndexEncodingVersion, 10, 1, 1, 0, byte(shapeKindPolyline)}, huge...),
		// One polyline claiming the maximum vertex count, but truncated.
		{shapeIndexEncodingVersion, 10, 1, 1, 0, byte(shapeKindPolyline), 0x80, 0xe1, 0xeb, 0x17},
		// Lax polygon with a huge loop count.
		{shapeIndexEncodingVersion, 10, 1, 1, 0, byte(shapeKindLaxPolygon), 0x80, 0xad, 0xe2, 0x04},
		// An unknown shape kind.
		{shapeIndexEncodingVersion, 10, 1, 1, 0, 99},
		// A huge cell count.
		append([]byte{shapeIndexEncodingVersion, 10, 0, 0}, huge...),
		// A cell referencing a missing shape.
		{shapeIndexEncodingVersion, 10, 0, 0, 1, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x10, 1, 0, 0, 0},
	} {
		if err := NewShapeIndex().Decode(bytes.NewReader(tc)); err == nil {
			t.Errorf("Decode(%v) succeeded, want error", tc)
		}
	}
}

func TestShapeIndexDecodeErrorLeavesIndexUnchanged(t *testing.T) {
	index := allShapeTypesIndex()
	index.Build()
	before := index.Len()
	if err := index.Decode(bytes.NewReader([]byte{shapeIndexEncodingVersion, 10})); err == nil {
		t.Fatalf("Decode() succeeded, want error")
	}
	if index.Len() != before || len(index.cells) == 0 {
		t.Errorf("failed Decode modified the index")
	}
}

